#include <iostream>
using namespace std;

template<size_t N>
class RingBuffer {
    int data[N];
    size_t head = 0, tail = 0;
public:
    bool push(int val) {
        size_t next = (head + 1) % N;
        if (next == tail) return false;
        data[head] = val;
        head = next;
        return true;
    }
    bool pop(int& val) {
        if (tail == head) return false;
        val = data[tail];
        tail = (tail + 1) % N;
        return true;
    }
};

int main() {
    RingBuffer<8> rb;
    rb.push(10); rb.push(20); rb.push(30);
    int val;
    rb.pop(val); cout << "Popped: " << val << endl;
    rb.pop(val); cout << "Popped: " << val << endl;
    return 0;
}
